// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newMigrator) public {
        vm.assume(newMigrator != address(0));
        c.setMigrator(newMigrator);
        c.addReward(address(0x1));
        assertTrue(c.migrator() == newMigrator);
    }
}

